-- Restore the production Realtime publication membership without creating pg_cron jobs.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    if not exists (
      select 1
      from pg_publication p
      join pg_publication_rel pr on pr.prpubid = p.oid
      join pg_class c on c.oid = pr.prrelid
      join pg_namespace n on n.oid = c.relnamespace
      where p.pubname = 'supabase_realtime'
        and n.nspname = 'public'
        and c.relname = 'location_bookable_items'
    ) then
      alter publication supabase_realtime add table public.location_bookable_items;
    end if;

    if not exists (
      select 1
      from pg_publication p
      join pg_publication_rel pr on pr.prpubid = p.oid
      join pg_class c on c.oid = pr.prrelid
      join pg_namespace n on n.oid = c.relnamespace
      where p.pubname = 'supabase_realtime'
        and n.nspname = 'public'
        and c.relname = 'location_reservations'
    ) then
      alter publication supabase_realtime add table public.location_reservations;
    end if;
  else
    raise exception 'supabase_realtime publication is missing';
  end if;
end
$$;
